const baseUrl = 'http://host.docker.internal:3000';
const imageUrl = `${baseUrl}/vercel.svg`;

// Fetch the image file
fetch(imageUrl)
  .then(response => response.blob())
  .then(blob => {
    // Extract metadata from the blob
    const metadata = blob.metadata();
    return {
      url: imageUrl,
      metadata: metadata
    };
  })
  .catch(error => {
    return {
      url: imageUrl,
      error: error.message
    };
  });

